using System;using System.IO;using System.Text;using System.Linq;using System.Collections.Generic;using System.Net.Http;using System.Net.Http.Headers;
namespace FocusGrowth {
public sealed class ContinuousGrant {
 readonly Disk disk;readonly string device;public ContinuousGrant(string folder,string deviceId){disk=new Disk(folder);device=deviceId;}
 public bool Valid {get{var g=disk.Load("continuous-authorization");DateTime until;return g!=null&&J.Str(J.Get(g,"scope"))=="continuous-projects-tasks-plans-v1"&&J.Str(J.Get(g,"repository"))=="tang0709/focus-growth-data"&&J.Str(J.Get(g,"path"))=="sync/state.json"&&J.Str(J.Get(g,"device"))==device&&DateTime.TryParse(J.Str(J.Get(g,"untilUtc")),out until)&&until.ToUniversalTime()>DateTime.UtcNow;}}
 // Called ONLY by the separate native authorization dialog after a later explicit user request.
 internal void Issue(string consentReference,string baselineSha,string backupDigest){Schema.Require(!String.IsNullOrWhiteSpace(consentReference)&&consentReference.Length>=12,"explicit_consent_reference_required");Schema.Require(System.Text.RegularExpressions.Regex.IsMatch(baselineSha??"","^[a-f0-9]{40}$")&&System.Text.RegularExpressions.Regex.IsMatch(backupDigest??"","^[a-f0-9]{64}$"),"authorization_baseline_required");disk.Save("continuous-authorization",new{scope="continuous-projects-tasks-plans-v1",repository="tang0709/focus-growth-data",path="sync/state.json",device=device,consentReference=consentReference,baselineSha=baselineSha,backupDigest=backupDigest,grantedUtc=DateTime.UtcNow.ToString("o"),untilUtc=DateTime.UtcNow.AddDays(7).ToString("o")});}
}
public sealed class ContinuousCloud:ITransport,IDisposable {
 readonly Cloud reader;readonly bool production;readonly Func<bool> allowed;readonly HttpClient writer;public bool TestOffline;DateTime verified=DateTime.MinValue;
 public ContinuousCloud(string path,bool prod,Func<bool> canWrite){production=prod;Schema.Require(prod?path=="sync/state.json":System.Text.RegularExpressions.Regex.IsMatch(path,"^sync/tests/v04-[a-f0-9]{32}\\.json$"),"workspace_path_rejected");reader=new Cloud(path,prod);allowed=canWrite;if(prod){writer=new HttpClient(new HttpClientHandler{AllowAutoRedirect=false});writer.Timeout=TimeSpan.FromSeconds(20);writer.DefaultRequestHeaders.UserAgent.ParseAdd("FocusGrowthSync/0.4");writer.DefaultRequestHeaders.Accept.Add(new MediaTypeWithQualityHeaderValue("application/vnd.github+json"));writer.DefaultRequestHeaders.Add("X-GitHub-Api-Version","2022-11-28");writer.DefaultRequestHeaders.Authorization=new AuthenticationHeaderValue("Bearer",CredentialStore.Read());}}
 void Online(){if(TestOffline){Schema.Require(!production,"synthetic_control_only");throw new Fault("offline");}}
 public Snapshot Read(Snapshot cached){Online();if((DateTime.UtcNow-verified).TotalSeconds>=60){reader.Verify();verified=DateTime.UtcNow;}var s=reader.Read(cached);if(production)Schema.Require(s.Sha!=null&&(bool)s.State["initialized"]&&(int)s.State["revision"]>=1,"production_not_initialized");if(cached!=null&&cached.Sha!=null)Schema.Require((int)s.State["revision"]>=(int)cached.State["revision"],"remote_revision_regression");return s;}
 public void Write(Dictionary<string,object> state,string sha){Schema.Require(allowed(),"continuous_authorization_required_or_paused");Online();Schema.Validate(state);if(!production){reader.Write(state,sha);return;}reader.Verify();var before=reader.Read(null);Schema.Require(before.Sha==sha,"sha_conflict");Schema.Require((bool)before.State["initialized"]&&(bool)state["initialized"]&&(int)state["revision"]==(int)before.State["revision"]+1,"production_revision_invalid");foreach(string c in Schema.Collections){var afterIds=Schema.Map(state,c);Schema.Require(Schema.Map(before.State,c).Keys.All(afterIds.ContainsKey),"deletion_disabled");}var oldOps=J.Arr(before.State["operationIds"]);var ops=J.Arr(state["operationIds"]);Schema.Require(ops.Count==oldOps.Count+1&&oldOps.All(ops.Contains),"operation_history_invalid");Schema.Require(allowed(),"continuous_authorization_required_or_paused");try{using(var response=writer.PutAsync("https://api.github.com/repos/tang0709/focus-growth-data/contents/sync/state.json",new StringContent(J.Dump(new{message="Apply authorized Focus Growth field changes",branch="main",sha=sha,content=Convert.ToBase64String(Encoding.UTF8.GetBytes(J.Dump(state)))}),Encoding.UTF8,"application/json")).GetAwaiter().GetResult()){if((int)response.StatusCode==409||(int)response.StatusCode==422)throw new Fault("sha_conflict");if((int)response.StatusCode==403||(int)response.StatusCode==429)throw new Fault("rate_limited_or_forbidden");Schema.Require((int)response.StatusCode==200,"cloud_write_failed");}}catch(Fault){throw;}catch{throw new Fault("offline");}}
 public void Dispose(){reader.Dispose();if(writer!=null){writer.DefaultRequestHeaders.Authorization=null;writer.Dispose();}}
}
public sealed class ContinuousController {
 readonly object gate=new object();readonly Engine engine;readonly LocalVault vault;readonly Func<bool> authorization;readonly Disk disk;string owner;DateTime touched;bool attached;public readonly bool Production;public readonly string Device;public bool Enabled{get;private set;}public Action<bool> NetworkControl;
 public ContinuousController(bool prod,string device,ITransport cloud,Disk store,LocalVault backups,Func<bool> grant){Production=prod;Device=device;disk=store;vault=backups;authorization=grant;engine=new Engine(cloud,store);Enabled=false;}
 public bool Authorized {get{return !Production||authorization();}}
 void Owner(string id){Schema.Id(id);Schema.Require(attached&&id==owner,"workspace_lease_required");touched=DateTime.UtcNow;}
 public object Attach(Dictionary<string,object> request,string origin){lock(gate){Schema.Require(request.Count==3,"invalid_attach");string id=J.Str(request["clientId"]);Schema.Id(id);Schema.Require(!attached||owner==id||(DateTime.UtcNow-touched).TotalSeconds>60,"workspace_in_use");var source=J.Obj(request["source"]);Schema.Require(J.Str(J.Get(source,"storageKey"))==(Production?"start-workbench-v1":"start-workbench-sync-test-v04"),"storage_key_mismatch");if(Production)Schema.Require(origin==Bridge.Pages&&J.Str(J.Get(source,"origin"))==Bridge.Pages&&J.Str(J.Get(source,"pathname"))=="/focus-growth/","production_source_mismatch");var db=J.Obj(LocalJson.Parse(J.Str(request["raw"])));PreparationModel.ValidateFull(db);Schema.Require(J.Get(db,"demo") is bool&&!(bool)db["demo"],"demo_not_allowed");if(Production)Schema.Require(Schema.Collections.Any(c=>J.Arr(db[c]).Count>0),"empty_production_source");var backup=vault.SaveVerified("attach",Encoding.UTF8.GetBytes(LocalJson.Dump(db)));owner=id;attached=true;touched=DateTime.UtcNow;disk.Save("attach",new{clientId=id,source=source,backup=backup});return new{backup=backup,mode=Production?"production":"synthetic",authorized=Authorized,enabled=Enabled,device=Device};}}
 public object Checkpoint(Dictionary<string,object> request){lock(gate){Owner(J.Str(J.Get(request,"clientId")));Schema.Require(request.Count==2,"invalid_checkpoint");string raw=J.Str(J.Get(request,"raw"));PreparationModel.ValidateFull(J.Obj(LocalJson.Parse(raw)));return vault.SaveVerified("before-incoming",Encoding.UTF8.GetBytes(raw));}}
 public void Resume(string id){lock(gate){Owner(id);Schema.Require(Authorized,"continuous_authorization_required");Enabled=true;disk.Save("runtime",new{paused=false});}}
 public void Pause(){lock(gate){Enabled=false;disk.Save("runtime",new{paused=true});}}
 public void ResumeCurrent(){lock(gate){Schema.Require(attached,"pair_and_attach_first");Resume(owner);}}
 public void Release(){lock(gate){Pause();owner=null;attached=false;}}
 public void Queue(Dictionary<string,object> request,bool resolve){lock(gate){Owner(J.Str(J.Get(request,"clientId")));Schema.Require(Authorized&&Enabled,"continuous_authorization_required_or_paused");var body=J.Copy(request);body.Remove("clientId");if(resolve)engine.Resolve(body);else engine.Queue(body);}}
 public void SetNetwork(bool offline){lock(gate){Schema.Require(!Production&&NetworkControl!=null,"synthetic_control_only");NetworkControl(offline);}}
 public void Tick(bool manual){if(!System.Threading.Monitor.TryEnter(gate))return;try{if(Enabled&&!Authorized){Enabled=false;disk.Save("runtime",new{paused=true});}if(Enabled)engine.Sync(manual);else engine.RefreshReadOnly(manual);if(new[]{"unsupported_schema","remote_revision_regression","production_not_initialized"}.Contains(engine.Error)){Enabled=false;disk.Save("runtime",new{paused=true});}}finally{System.Threading.Monitor.Exit(gate);}}
 public Dictionary<string,object> View(){lock(gate){var v=engine.View();v["version"]="0.4";v["mode"]=Production?"production":"synthetic";v["enabled"]=Enabled;v["authorized"]=Authorized;v["productionLocked"]=Production&&!Authorized;v["device"]=Device;if(!Enabled)v["status"]="已暂停 · 只读";return v;}}
}
}
